const http = require("http");
const { createClient } = require("@clickhouse/client");

const clickhouseUrl = process.env.CLICKHOUSE_URL || "http://localhost:8123";

// Create a pool of clients to handle concurrent requests safely.
// Each client maintains its own HTTP connection, avoiding stream interleaving.
const POOL_SIZE = 10;
const clients = Array.from({ length: POOL_SIZE }, () =>
  createClient({
    url: clickhouseUrl,
    request_timeout: 30000,
    max_open_connections: 1,
  })
);
let nextClient = 0;

function getClient() {
  const c = clients[nextClient];
  nextClient = (nextClient + 1) % POOL_SIZE;
  return c;
}

const server = http.createServer(async (req, res) => {
  if (req.url !== "/api/metrics") {
    res.writeHead(404);
    res.end(JSON.stringify({ error: "Not found" }));
    return;
  }
  try {
    const c = getClient();
    const r = await c.query({
      query: "SELECT sum(value) AS total FROM analytics.metrics",
      format: "JSONEachRow",
    });
    const rows = await r.json();
    const total = rows[0]?.total ?? 0;
    res.setHeader("Content-Type", "application/json");
    res.end(JSON.stringify({ total }));
  } catch (e) {
    res.writeHead(500);
    res.end(JSON.stringify({ error: String(e.message) }));
  }
});

server.listen(3000, () => console.log("API on :3000"));
